import{_ as a,C as d,o as c,c as l,a2 as o,E as i}from"./chunks/framework.CBxkvBm_.js";const f=JSON.parse('{"title":"Modelica 3.x (.mo)","description":"","frontmatter":{},"headers":[],"relativePath":"languages/modelica.md","filePath":"languages/modelica.md"}'),r={name:"languages/modelica.md"};function s(n,e,m,p,g,u){const t=d("MermaidBlock");return c(),l("div",null,[e[0]||(e[0]=o('<h1 id="modelica-3-x-mo" tabindex="-1">Modelica 3.x (<code>.mo</code>) <a class="header-anchor" href="#modelica-3-x-mo" aria-label="Permalink to &quot;Modelica 3.x (`.mo`)&quot;">​</a></h1><p><code>@modelscript/modelica</code> (<code>languages/modelica</code>) is the flagship physical modeling language of ModelScript. It provides a complete Modelica 3.x compiler pipeline—from a native WebAssembly GLR parser and Salsa query engine to an AssemblyScript/TypeScript arena flattener (<code>ModelicaFlattener</code>) and the full Modelica Standard Library (MSL 4.0.0).</p><hr><h2 id="compilation-pipeline" tabindex="-1">Compilation Pipeline <a class="header-anchor" href="#compilation-pipeline" aria-label="Permalink to &quot;Compilation Pipeline&quot;">​</a></h2>',4)),i(t,{code:"flowchart%20LR%0A%20%20%20%20MO%5B%22.mo%20Source%22%5D%20--%3E%20GLR%5B%22WASM%20GLR%20Parser%22%5D%0A%20%20%20%20GLR%20--%3E%20IDX%5B%22SymbolIndexer%20%26%20WorkspaceIndex%22%5D%0A%20%20%20%20IDX%20--%3E%20SALSA%5B%22QueryEngine%20(Salsa)%22%5D%0A%20%20%20%20SALSA%20--%3E%20LINT%5B%22CompilerLints%20%26%20Semantic%20Lints%22%5D%0A%20%20%20%20SALSA%20--%3E%20FLAT%5B%22ModelicaFlattener%20(Hybrid%20WASM%2FTS)%22%5D%0A%20%20%20%20FLAT%20--%3E%20DAE%5B%22DAEBuilder%20(Linear%20Memory)%22%5D%0A%20%20%20%20DAE%20--%3E%20SIM%5B%22BLT%20%2F%20Pantelides%20%2F%20IDA%20%2F%20CVODE%20%2F%20WebGPU%22%5D%0A"}),e[1]||(e[1]=o('<hr><h2 id="core-language-coverage" tabindex="-1">Core Language Coverage <a class="header-anchor" href="#core-language-coverage" aria-label="Permalink to &quot;Core Language Coverage&quot;">​</a></h2><ul><li><strong>Class Specializations</strong>: <code>model</code>, <code>block</code>, <code>connector</code>, <code>expandable connector</code>, <code>record</code>, <code>type</code>, <code>package</code>, <code>function</code>, <code>operator</code>, <code>operator record</code>, <code>operator function</code></li><li><strong>Inheritance &amp; Redeclarations</strong>: Multiple <code>extends</code>, <code>redeclare</code>, <code>replaceable</code>, <code>constrainedby</code>, <code>inner</code> / <code>outer</code> dynamic scoping, and deep hierarchical class modifications</li><li><strong>Equations &amp; Algorithms</strong>: Differential equations (<code>der(x)</code>), <code>connect(a, b)</code> (both potential/flow and <code>stream</code> connectors), <code>if</code>/<code>for</code>/<code>when</code> equations, <code>initial equation</code>, and imperative <code>algorithm</code> / <code>initial algorithm</code> sections</li><li><strong>Synchronous Clocks (Modelica 3.3+)</strong>: <code>Clock</code>, <code>sample</code>, <code>hold</code>, <code>previous</code>, <code>subSample</code>, <code>superSample</code>, <code>shiftSample</code>, <code>backSample</code></li></ul><hr><h2 id="polyglot-physical-extensions-languages-modelica-src-extensions" tabindex="-1">Polyglot &amp; Physical Extensions (<code>languages/modelica/src/extensions/</code>) <a class="header-anchor" href="#polyglot-physical-extensions-languages-modelica-src-extensions" aria-label="Permalink to &quot;Polyglot &amp; Physical Extensions (`languages/modelica/src/extensions/`)&quot;">​</a></h2><p>Beyond standard Modelica 3.x, <code>@modelscript/modelica</code> includes first-class compiler extensions for 3D CAD geometry, multiphysics FEA/CFD studies, formal verification, and localization:</p><ol><li><strong>Embedded 3D CSG &amp; STEP Export (<code>shape-flattener.ts</code>, <code>csg.ts</code>, <code>cad.ts</code>)</strong>: <ul><li><code>ShapeFlattener</code> extracts <code>Modelica.Mechanics.MultiBody.Visualizers.FixedShape</code> components, parametric dimensions, and <code>Placement</code> transformations directly from flattened models.</li><li>Compiles visualizers into parametric OpenSCAD scripts (<code>npx msx csg ModelName file.mo</code>) or exports watertight ISO 10303-21 STEP B-Rep geometry via the <code>modelscript/exportShapeToStep</code> LSP command.</li></ul></li><li><strong>Embedded FEA &amp; CFD Multiphysics Studies (<code>study-flattener.ts</code>, <code>studies.ts</code>)</strong>: <ul><li><code>StudyFlattener</code> (<code>modelscript/flattenStudy</code>) extracts embedded structural and fluid study annotations, material properties, and boundary conditions from Modelica components to synthesize CalculiX (<code>.inp</code>) and SU2 (<code>.cfg</code>) solver decks.</li></ul></li><li><strong>Octagon Abstract Interpretation &amp; Formal Safety Verification (<code>src/formal/</code>)</strong>: <ul><li><code>ModelicaCfgLowerer</code> (<code>modelica-cfg-lowerer.ts</code>), <code>ModelicaAbstractEvaluator</code> (<code>modelica-abstract-evaluator.ts</code>), and <code>ModelicaStaticAnalyzer</code> (<code>modelica-analyzer.ts</code>) lower flattened DAE equations and <code>algorithm</code> statements into relational Control Flow Graphs evaluated over the <strong>Octagon Abstract Domain</strong> ($\\pm x_i \\pm x_j \\le c$).</li><li><code>PhysicalInvariantBridge</code> (<code>physical-invariant-bridge.ts</code>) proves division-by-zero freedom, square-root/logarithm domain safety, and physical state invariants (<code>domain.octagon()</code>).</li></ul></li><li><strong>Gettext <code>.po</code> / <code>.pot</code> Internationalization (<code>po.ts</code>)</strong>: <ul><li>Extracts translatable description strings and <code>Dialog</code>/<code>Documentation</code> annotations into GNU Gettext <code>.pot</code> templates and merges localized <code>.po</code> catalogs (<code>npx msx i18n</code>).</li></ul></li></ol><hr><h2 id="semantic-linter-languages-modelica-src-lints" tabindex="-1">Semantic Linter (<code>languages/modelica/src/lints/</code>) <a class="header-anchor" href="#semantic-linter-languages-modelica-src-lints" aria-label="Permalink to &quot;Semantic Linter (`languages/modelica/src/lints/`)&quot;">​</a></h2><p>ModelScript enforces over 60 OpenModelica-compatible diagnostic rules across six modular analyzers:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Module</th><th style="text-align:left;">Representative Checks</th></tr></thead><tbody><tr><td style="text-align:left;"><code>syntax-placement.ts</code></td><td style="text-align:left;"><code>M1001</code>–<code>M1003</code>: Parse errors, missing tokens, empty array constructors</td></tr><tr><td style="text-align:left;"><code>queries.ts</code></td><td style="text-align:left;"><code>M2001</code>–<code>M2005</code>: Duplicate elements, unresolved variables/classes/modifiers, identifier mismatches</td></tr><tr><td style="text-align:left;"><code>types-expressions.ts</code></td><td style="text-align:left;"><code>M3001</code>–<code>M3006</code>: Binding/modifier/argument type mismatches, array dimension checks</td></tr><tr><td style="text-align:left;"><code>hierarchy-variability.ts</code></td><td style="text-align:left;"><code>M4001</code>–<code>M4005</code>: Circular <code>extends</code>, duplicate modifications, <code>protected</code> access violations, variability ordering</td></tr><tr><td style="text-align:left;"><code>connections-streams.ts</code></td><td style="text-align:left;"><code>M3003</code>–<code>M3004</code>: Connector plug-compatibility, stream connector rules, cardinality checks</td></tr><tr><td style="text-align:left;"><code>synchronous-clocks.ts</code> &amp; <code>cfa.ts</code></td><td style="text-align:left;">Clock partitioning rules, uninitialized discrete variables, structural singularity diagnostics</td></tr></tbody></table><hr><h2 id="dedicated-modelica-mcp-server-tools" tabindex="-1">Dedicated <code>modelica-mcp</code> Server Tools <a class="header-anchor" href="#dedicated-modelica-mcp-server-tools" aria-label="Permalink to &quot;Dedicated `modelica-mcp` Server Tools&quot;">​</a></h2><p>The <code>@modelscript/modelica</code> MCP server (<code>languages/modelica/src/mcp.ts</code>) exposes 7 tools to AI agents:</p><table tabindex="0"><thead><tr><th style="text-align:left;">MCP Tool</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>modelica_load</code></td><td style="text-align:left;">Loads <code>.mo</code> files or Modelica Standard Library packages into the persistent workspace session</td></tr><tr><td style="text-align:left;"><code>modelica_parse</code></td><td style="text-align:left;">Parses Modelica source code with the WASM GLR parser and returns CST nodes and syntax diagnostics</td></tr><tr><td style="text-align:left;"><code>modelica_flatten</code></td><td style="text-align:left;">Flattens a Modelica class via <code>ModelicaFlattener</code> and returns the flat Modelica DAE representation</td></tr><tr><td style="text-align:left;"><code>modelica_simulate</code></td><td style="text-align:left;">Flattens, runs BLT/index reduction, integrates the DAE over $[t_0, t_{\\text{stop}}]$, and returns trajectory time-series</td></tr><tr><td style="text-align:left;"><code>modelica_doe</code></td><td style="text-align:left;">Executes a multi-parameter Design of Experiments (Full Factorial / Latin Hypercube) batch sweep</td></tr><tr><td style="text-align:left;"><code>modelica_sensitivity</code></td><td style="text-align:left;">Computes local finite-difference or forward sensitivity matrices $\\partial y_i / \\partial p_j$ for target outputs</td></tr><tr><td style="text-align:left;"><code>modelica_query</code></td><td style="text-align:left;">Queries the Salsa <code>QueryEngine</code> for class components, resolved types, variabilities, and modifications</td></tr></tbody></table><hr><h2 id="sysml-v2-transformer-polyglot-tgg-rules" tabindex="-1">SysML v2 Transformer &amp; Polyglot TGG Rules <a class="header-anchor" href="#sysml-v2-transformer-polyglot-tgg-rules" aria-label="Permalink to &quot;SysML v2 Transformer &amp; Polyglot TGG Rules&quot;">​</a></h2><ul><li><strong>Direct AST Transformer (<code>modelicaToSysML2</code> in <code>languages/modelica/src/transformers/sysml2.ts</code>)</strong>: Converts complete Modelica packages and models into idiomatic SysML v2 textual notation (<code>part def</code>, <code>port def</code>, <code>attribute</code>, <code>connect</code>).</li><li><strong>10 Bidirectional TGG Rules (<code>languages/modelica/src/language.ts</code>)</strong>: <ul><li><strong>Modelica $\\leftrightarrow$ SysML v2 (6 rules)</strong>: <code>ModelicaModelToSysML2PartDef</code>, <code>ModelicaConnectorToSysML2PortDef</code>, <code>ModelicaComponentToSysML2Part</code>, <code>ModelicaParameterToSysML2Attribute</code>, <code>ModelicaConnectorInstanceToSysML2Port</code>, <code>ModelicaConnectToSysML2Connection</code></li><li><strong>Modelica $\\leftrightarrow$ OWL2 (2 rules)</strong>: <code>ModelicaModelToOWL2Class</code>, <code>ModelicaParameterToOWL2DataProperty</code></li><li><strong>Modelica $\\leftrightarrow$ STEP (2 rules)</strong>: <code>ModelicaRevoluteToStepRevolute</code>, <code>ModelicaPrismaticToStepPrismatic</code></li></ul></li></ul>',18))])}const h=a(r,[["render",s]]);export{f as __pageData,h as default};
